#!/usr/bin/env bash
set -euo pipefail

repo_root="poe-usbc-25g-pro-v1"

if [ -e "$repo_root" ]; then
  echo "error: $repo_root already exists" >&2
  exit 1
fi

mkdir -p "$repo_root"
archive_line=$(awk '/^__ARCHIVE_BELOW__$/ { print NR + 1; exit }' "$0")
if [ -z "$archive_line" ]; then
  echo "error: archive marker not found" >&2
  exit 1
fi

tail -n +"$archive_line" "$0" \
  | python3 -c 'import sys, base64; sys.stdout.buffer.write(base64.b64decode(sys.stdin.buffer.read()))' \
  | tar -xzf - -C "$repo_root"

install -m 755 "$0" "$repo_root/initialize_repo.sh"

cd "$repo_root"
git init
git config user.name "Collin Wiggins"
git config user.email "collin@localhost"
git add .
git commit -m "Initial project scaffold from spec v1"

echo "Repository initialized at $repo_root"
exit 0
__ARCHIVE_BELOW__

